    )

    if (error) {
      console.error('Error checking revalidation history:', error)
      return new Response('Error checking revalidation history', { status: 500 })
    }

    const sixHoursAgo = new Date()
    sixHoursAgo.setHours(sixHoursAgo.getHours() - 6)

    const revalidatedRecently = (lastRevalidation ?? []).some(
      (revalidation: { created_at: string }) =>
        new Date(revalidation.created_at) > sixHoursAgo
    )

    if (revalidatedRecently) {
      return new Response('revalidated within the last 6 hours', { status: 429 })
    }
  }

  // Log the revalidation events. A logging failure should not block the
  // revalidation itself, so errors are only reported.
  const { error: insertError } = await supabase
    .from('validation_history')
    .insert(tags.map((tag) => ({ tag })))
  if (insertError) {
    console.error('Error logging revalidation history:', insertError)
  }

  for (const tag of tags) {
    revalidateTag(tag)
  }

  return new Response(null, {
    status: 204,
    headers: { 'Cache-Control': 'no-cache' },
  })
}

export async function POST(request: Request): Promise<Response> {
  try {
    return await _handleRevalidateRequest(request)
  } catch (error) {
    console.error('Error handling revalidation request:', error)
    return new Response('Internal server error', { status: 500 })
  }
}
